```C
static int safe_atou_optional_plus(const char *s, unsigned *ret_u) {
    /* Returns 1 if plus, 0 if no plus, negative on error */
    int r;
    const char *p = endswith(s, "+");
    if (p)
            s = strndupa(s, p - s);
    r =  safe_atou(s, ret_u);
    if (r < 0)
           return r;
    return !!p;
}
```
(or keep `*ret_has_plus`, whatever is more convenient).
